import React from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';
import AnimatedPomodoroTimer from '../components/AnimatedPomodoroTimer';

const Pomodoro = ({ tasks }) => {
  const { theme } = useTheme();
  
  const pageVariants = {
    initial: { opacity: 0, y: 20 },
    animate: { 
      opacity: 1, 
      y: 0,
      transition: { 
        duration: 0.5,
        ease: "easeOut" 
      }
    },
    exit: { 
      opacity: 0,
      y: -20,
      transition: { 
        duration: 0.3 
      }
    }
  };
  
  return (
    <motion.div
      initial="initial"
      animate="animate"
      exit="exit"
      variants={pageVariants}
      className="max-w-5xl mx-auto"
    >
      <div className="mb-6 text-center">
        <h1 className={`text-4xl font-bold ${theme.text.primary}`}>
          Pomodoro Timer
        </h1>
        <p className={`text-lg mt-2 ${theme.text.secondary}`}>
          Focus on your work with timed sessions
        </p>
      </div>
      
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg`}>
          <AnimatedPomodoroTimer tasks={tasks} />
        </div>
        
        <div className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg`}>
          <h2 className={`text-xl font-semibold mb-4 ${theme.text.primary}`}>About the Pomodoro Technique</h2>
          
          <div className={`space-y-4 ${theme.text.secondary}`}>
            <p>
              The Pomodoro Technique is a time management method developed by Francesco Cirillo in the late 1980s.
            </p>
            
            <div className="flex items-start">
              <motion.div 
                className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center mr-3 flex-shrink-0 text-white font-bold"
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
              >
                1
              </motion.div>
              <p>Choose a task you want to work on</p>
            </div>
            
            <div className="flex items-start">
              <motion.div 
                className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center mr-3 flex-shrink-0 text-white font-bold"
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
              >
                2
              </motion.div>
              <p>Set the timer for 25 minutes and focus exclusively on that task</p>
            </div>
            
            <div className="flex items-start">
              <motion.div 
                className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center mr-3 flex-shrink-0 text-white font-bold"
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
              >
                3
              </motion.div>
              <p>When the timer rings, take a 5-minute break</p>
            </div>
            
            <div className="flex items-start">
              <motion.div 
                className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center mr-3 flex-shrink-0 text-white font-bold"
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
              >
                4
              </motion.div>
              <p>After 4 pomodoros, take a longer break (15-30 minutes)</p>
            </div>
          </div>
          
          <div className="mt-6">
            <h3 className={`text-lg font-medium mb-2 ${theme.text.primary}`}>Benefits:</h3>
            <ul className={`list-disc list-inside space-y-2 ${theme.text.secondary}`}>
              <motion.li 
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.2 }}
              >
                Reduces anxiety associated with beginning large tasks
              </motion.li>
              <motion.li 
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.3 }}
              >
                Increases focus and concentration by cutting down interruptions
              </motion.li>
              <motion.li 
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.4 }}
              >
                Builds a better sense of how long tasks take to complete
              </motion.li>
              <motion.li 
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.5 }}
              >
                Creates a clear structure for study sessions
              </motion.li>
            </ul>
          </div>
          
          <motion.div 
            className="mt-6 p-4 border-l-4 border-blue-500 bg-blue-500 bg-opacity-10 rounded"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.6 }}
          >
            <p className={`italic ${theme.text.secondary}`}>
              "The Pomodoro Technique not only helps you get more done, but it helps prevent burnout by ensuring you take regular breaks."
            </p>
          </motion.div>
        </div>
      </div>
    </motion.div>
  );
};

export default Pomodoro; 