import React, { createContext, useContext, useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const NotificationContext = createContext();

export const useNotification = () => useContext(NotificationContext);

export const NotificationProvider = ({ children }) => {
  const [notifications, setNotifications] = useState([]);
  const [autoNotify, setAutoNotify] = useState(() => {
    // Get saved preference from localStorage or default to true
    const savedPreference = localStorage.getItem('autoNotify');
    return savedPreference !== null ? JSON.parse(savedPreference) : true;
  });

  // Save autoNotify preference to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('autoNotify', JSON.stringify(autoNotify));
  }, [autoNotify]);

  const addNotification = (message, type = 'info', duration = 5000) => {
    // Skip notifications if autoNotify is disabled (except for critical ones)
    if (!autoNotify && type !== 'error' && type !== 'critical') {
      return;
    }
    
    const id = Date.now() + Math.random().toString(36).substr(2, 5);
    
    setNotifications(prev => [...prev, {
      id,
      message,
      type,
      duration
    }]);
    
    if (duration > 0) {
      setTimeout(() => {
        dismissNotification(id);
      }, duration);
    }
    
    return id;
  };
  
  const dismissNotification = (id) => {
    setNotifications(prev => prev.filter(notification => notification.id !== id));
  };
  
  const toggleAutoNotify = () => {
    setAutoNotify(prev => !prev);
  };

  return (
    <NotificationContext.Provider value={{ 
      notifications, 
      addNotification, 
      dismissNotification, 
      autoNotify,
      toggleAutoNotify 
    }}>
      {children}
      <NotificationDisplay />
    </NotificationContext.Provider>
  );
};

const Notification = ({ id, message, type, onClose }) => {
  const notificationTypes = {
    success: "bg-green-500",
    error: "bg-red-500",
    warning: "bg-yellow-500",
    info: "bg-blue-500"
  };

  React.useEffect(() => {
    const timer = setTimeout(() => {
      onClose(id);
    }, 5000);
    return () => clearTimeout(timer);
  }, [id, onClose]);

  return (
    <motion.div 
      className={`${notificationTypes[type]} text-white p-4 rounded-lg shadow-lg backdrop-blur-lg bg-opacity-80 flex items-center justify-between max-w-md w-full`}
      initial={{ opacity: 0, y: -50, scale: 0.9 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, y: -20, scale: 0.9 }}
      transition={{ type: "spring", stiffness: 500, damping: 30 }}
      layout
    >
      <p>{message}</p>
      <motion.button 
        whileHover={{ scale: 1.2 }}
        whileTap={{ scale: 0.9 }}
        className="ml-4 text-white focus:outline-none"
        onClick={() => onClose(id)}
      >
        <svg 
          xmlns="http://www.w3.org/2000/svg" 
          width="16" 
          height="16" 
          viewBox="0 0 24 24" 
          fill="none" 
          stroke="currentColor" 
          strokeWidth="2" 
          strokeLinecap="round" 
          strokeLinejoin="round"
        >
          <line x1="18" y1="6" x2="6" y2="18"></line>
          <line x1="6" y1="6" x2="18" y2="18"></line>
        </svg>
      </motion.button>
    </motion.div>
  );
};

const NotificationDisplay = () => {
  const { notifications, dismissNotification } = useContext(NotificationContext);

  return (
    <div className="fixed top-4 right-4 z-50 flex flex-col space-y-4">
      <AnimatePresence>
        {notifications.map((notification) => (
          <Notification
            key={notification.id}
            id={notification.id}
            message={notification.message}
            type={notification.type}
            onClose={dismissNotification}
          />
        ))}
      </AnimatePresence>
    </div>
  );
};

export const { addNotification } = useNotification; 