import React from 'react';
import DashboardContainer from '../components/dashboard/DashboardContainer';
import { pageVariants } from '../animations/pageAnimations';
import { motion } from 'framer-motion';

// Sample data for the dashboard
const sampleStudyData = [
  { day: 'Mon', value: 120 }, // 2 hours
  { day: 'Tue', value: 180 }, // 3 hours
  { day: 'Wed', value: 90 },  // 1.5 hours
  { day: 'Thu', value: 240 }, // 4 hours
  { day: 'Fri', value: 150 }, // 2.5 hours
  { day: 'Sat', value: 60 },  // 1 hour
  { day: 'Sun', value: 210 }, // 3.5 hours
];

const sampleTasks = [
  { id: 1, title: 'Read Chapter 5', completed: true, priority: 'high', dueDate: '2023-03-15' },
  { id: 2, title: 'Complete Math Problems', completed: true, priority: 'medium', dueDate: '2023-03-16' },
  { id: 3, title: 'Write Essay Draft', completed: false, priority: 'high', dueDate: '2023-03-18' },
  { id: 4, title: 'Physics Lab Report', completed: false, priority: 'medium', dueDate: '2023-03-20' },
  { id: 5, title: 'Study for Midterm', completed: false, priority: 'high', dueDate: '2023-03-22' },
];

const Dashboard = () => {
  return (
    <motion.div 
      className="max-w-7xl mx-auto px-4"
      variants={pageVariants}
      initial="initial"
      animate="animate"
      exit="exit"
    >
      <DashboardContainer 
        studyData={sampleStudyData} 
        tasks={sampleTasks} 
      />
    </motion.div>
  );
};

export default Dashboard; 