import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';
import BookPageFlip from '../components/BookPageFlip';
import BookListWithThumbnails from '../components/BookListWithThumbnails';
import PDFViewer from '../components/PDFViewer';
import { pageVariants, itemVariants } from '../animations/pageAnimations';
import { useSwipeable } from 'react-swipeable';

const Books = ({ pages }) => {
  const { theme } = useTheme();
  const [searchQuery, setSearchQuery] = useState('');
  const [uploadModalOpen, setUploadModalOpen] = useState(false);
  const [selectedBook, setSelectedBook] = useState(null);
  const [viewMode, setViewMode] = useState('reader'); // 'reader' or 'pdf'
  const [categoryFilter, setCategoryFilter] = useState(null);
  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadForm, setUploadForm] = useState({
    title: '',
    author: '',
    category: '',
    description: ''
  });
  
  // Enable keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      // Escape key to return to reader
      if (e.key === 'Escape' && viewMode === 'pdf') {
        handleBackToReader();
      }
    };
    
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [viewMode]);
  
  // Handle book selection
  const handleBookSelect = (book) => {
    // If this is a category selection
    if (book.category !== undefined && !book.path) {
      setCategoryFilter(book.category);
      return;
    }
    
    setSelectedBook(book);
    setViewMode('pdf');
  };
  
  const handleBackToReader = () => {
    setViewMode('reader');
  };
  
  // Handle file upload
  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file && file.type === 'application/pdf') {
      setSelectedFile(file);
      
      // Auto-populate title from filename
      const fileName = file.name.replace('.pdf', '');
      setUploadForm({
        ...uploadForm,
        title: fileName
      });
    }
  };
  
  const handleUploadFormChange = (e) => {
    const { name, value } = e.target;
    setUploadForm({
      ...uploadForm,
      [name]: value
    });
  };
  
  const handleUploadSubmit = (e) => {
    e.preventDefault();
    
    // In a real app, this would upload the file to the server
    // For demo purposes, we'll just close the modal
    setUploadModalOpen(false);
    
    // Reset form
    setSelectedFile(null);
    setUploadForm({
      title: '',
      author: '',
      category: '',
      description: ''
    });
  };
  
  // Swipe handlers
  const swipeHandlers = useSwipeable({
    onSwipedDown: () => {
      if (viewMode === 'pdf') {
        handleBackToReader();
      }
    },
    preventDefaultTouchmoveEvent: true,
    trackMouse: false
  });
  
  const demoBooks = [
    {
      id: 1,
      title: 'Advanced React Techniques',
      author: 'Jane Smith',
      coverImage: 'https://via.placeholder.com/150/3B82F6/FFFFFF?text=React',
      pages: 234,
      progress: 65,
      lastOpened: '2023-10-15'
    },
    {
      id: 2,
      title: 'JavaScript: The Good Parts',
      author: 'Douglas Crockford',
      coverImage: 'https://via.placeholder.com/150/F59E0B/FFFFFF?text=JS',
      pages: 176,
      progress: 100,
      lastOpened: '2023-09-22'
    },
    {
      id: 3,
      title: 'Design Patterns in Python',
      author: 'Alex Johnson',
      coverImage: 'https://via.placeholder.com/150/10B981/FFFFFF?text=Python',
      pages: 320,
      progress: 25,
      lastOpened: '2023-10-28'
    }
  ];
  
  const filteredBooks = demoBooks.filter(book => 
    book.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
    book.author.toLowerCase().includes(searchQuery.toLowerCase())
  );
  
  return (
    <motion.div
      initial="initial"
      animate="animate"
      exit="exit"
      variants={pageVariants}
      className="max-w-6xl mx-auto overflow-visible"
    >
      <div className="mb-6 md:mb-8 text-center relative">
        <div className="absolute inset-0 bg-gradient-to-r from-indigo-500/20 via-purple-500/20 to-pink-500/20 blur-3xl -z-10 opacity-50 rounded-full"></div>
        <h1 className={`text-4xl md:text-5xl font-bold ${theme.text.primary} drop-shadow-lg pb-2 bg-clip-text text-transparent bg-gradient-to-r from-blue-500 to-purple-600`}>
          Book Library
        </h1>
        <p className={`text-base md:text-lg mt-2 ${theme.text.secondary} font-medium tracking-wide`}>
          Manage and read your study materials
        </p>
      </div>
      
      {/* Search and Upload */}
      <motion.div 
        className={`p-4 md:p-5 rounded-2xl ${theme.card} backdrop-blur-xl shadow-2xl mb-6 flex flex-col sm:flex-row gap-4 border border-gray-700/30 relative overflow-hidden`}
        variants={itemVariants}
      >
        <div className="absolute inset-0 bg-gradient-to-br from-blue-500/10 to-purple-600/10 -z-10"></div>
        <div className="absolute -inset-[150px] backdrop-blur-3xl opacity-30 -z-10 animate-pulse"></div>
        
        <div className="relative flex-grow">
          <input
            type="text"
            placeholder="Search books..."
            className="w-full px-4 md:px-5 py-3 pl-12 bg-gray-800/70 text-white rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500/50 border border-gray-700/30 shadow-lg backdrop-blur-sm"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            className="h-5 w-5 absolute left-4 top-1/2 transform -translate-y-1/2 text-blue-400" 
            fill="none" 
            viewBox="0 0 24 24" 
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
        </div>
        <motion.button
          className="px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-700 text-white rounded-xl shadow-lg flex items-center justify-center hover:from-blue-700 hover:to-indigo-800 border border-blue-500/30 relative overflow-hidden group"
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={() => setUploadModalOpen(true)}
        >
          <div className="absolute inset-0 bg-gradient-to-r from-blue-400/20 to-indigo-400/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            className="h-5 w-5 mr-2 text-blue-200" 
            fill="none" 
            viewBox="0 0 24 24" 
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0l-4 4m4-4v12" />
          </svg>
          <span className="font-medium tracking-wide">Upload Book</span>
        </motion.button>
      </motion.div>
      
      {/* Mobile-first layout - Stack on mobile, grid on larger screens */}
      <div className="flex flex-col gap-6 md:grid md:grid-cols-2 md:gap-8">
        {/* Book List - Appears first on mobile */}
        <motion.div 
          className={`order-1 md:order-2 p-4 md:p-6 rounded-2xl ${theme.card} backdrop-blur-xl shadow-2xl relative overflow-hidden border border-gray-700/30`}
          variants={itemVariants}
        >
          <div className="absolute inset-0 bg-gradient-to-br from-purple-600/10 to-pink-600/5 -z-10"></div>
          <div className="absolute bottom-0 left-0 -mb-20 -ml-20 w-40 h-40 bg-purple-500/10 rounded-full blur-3xl"></div>
          
          <div className="flex items-center justify-between mb-5">
            <h2 className={`text-xl md:text-2xl font-semibold ${theme.text.primary} border-b border-gray-700/30 pb-2 inline-block`}>
              Your Books
            </h2>
            
            {categoryFilter && (
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className="flex items-center text-sm text-blue-400 hover:text-blue-300"
                onClick={() => setCategoryFilter(null)}
              >
                <span>Clear filter</span>
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </motion.button>
            )}
          </div>
          
          <BookListWithThumbnails 
            searchQuery={searchQuery}
            onSelectBook={handleBookSelect}
            categoryFilter={categoryFilter}
          />
        </motion.div>
        
        {/* Book Reader or PDF Viewer - Appears second on mobile */}
        <motion.div 
          className={`order-2 md:order-1 p-4 md:p-6 rounded-2xl ${theme.card} backdrop-blur-xl shadow-2xl relative overflow-hidden border border-gray-700/30 h-[min(600px,70vh)] md:h-auto`}
          variants={itemVariants}
          layout
          {...swipeHandlers}
        >
          <div className="absolute inset-0 bg-gradient-to-br from-indigo-600/10 to-blue-600/5 -z-10"></div>
          <div className="absolute top-0 right-0 -mt-10 -mr-10 w-32 h-32 bg-blue-500/20 rounded-full blur-3xl"></div>
          
          {viewMode === 'pdf' && selectedBook ? (
            <>
              <div className="flex items-center mb-4 md:mb-5">
                <motion.button
                  className="flex items-center text-blue-400 hover:text-blue-300 mr-4 transition-colors duration-300 group touch-manipulation"
                  whileHover={{ x: -3 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={handleBackToReader}
                >
                  <div className="p-2 rounded-full bg-blue-500/10 group-hover:bg-blue-500/20 transition-colors duration-300 mr-2">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                    </svg>
                  </div>
                  <span className="font-medium">Back</span>
                </motion.button>
                <h2 className={`text-lg md:text-xl font-semibold truncate ${theme.text.primary} pl-2 border-l-2 border-blue-500/30`}>{selectedBook.title}</h2>
              </div>
              <PDFViewer 
                pdfPath={selectedBook.path} 
                bookTitle={selectedBook.title} 
              />
            </>
          ) : (
            <>
              <h2 className={`text-xl md:text-2xl font-semibold mb-4 md:mb-5 ${theme.text.primary} border-b border-gray-700/30 pb-2 inline-block`}>Read Book</h2>
              <BookPageFlip pages={pages} />
            </>
          )}
        </motion.div>
      </div>
      
      {/* Upload Modal */}
      <AnimatePresence>
        {uploadModalOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-gray-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4 overflow-y-auto"
            onClick={() => setUploadModalOpen(false)}
          >
            <motion.div 
              className={`${theme.card} rounded-2xl p-5 md:p-8 border border-gray-700/30 shadow-2xl max-w-md w-full relative overflow-hidden`}
              initial={{ scale: 0.9, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.9, y: 20 }}
              onClick={(e) => e.stopPropagation()}
            >
              <div className="absolute inset-0 bg-gradient-to-br from-blue-600/10 to-purple-600/5 -z-10"></div>
              <div className="absolute top-0 right-0 -mt-10 -mr-10 w-32 h-32 bg-blue-500/10 rounded-full blur-3xl"></div>
              
              <div className="flex justify-between items-center mb-6">
                <h2 className={`text-xl md:text-2xl font-semibold ${theme.text.primary}`}>Upload Book</h2>
                <motion.button
                  whileHover={{ scale: 1.1, rotate: 90 }}
                  whileTap={{ scale: 0.9 }}
                  onClick={() => setUploadModalOpen(false)}
                  className="p-1 rounded-full bg-gray-800 text-gray-400 hover:text-white transition-colors"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </motion.button>
              </div>
              
              <form onSubmit={handleUploadSubmit} className="space-y-5">
                {/* File Upload */}
                <div className="space-y-2">
                  <label className={`block text-sm font-medium ${theme.text.secondary}`}>PDF File</label>
                  <div className={`border-2 border-dashed border-gray-700/50 rounded-xl p-6 text-center cursor-pointer hover:border-blue-500/50 transition-colors ${selectedFile ? 'bg-blue-500/10' : ''}`}>
                    <input
                      type="file"
                      accept=".pdf"
                      onChange={handleFileChange}
                      className="hidden"
                      id="file-upload"
                    />
                    <label htmlFor="file-upload" className="cursor-pointer w-full h-full flex flex-col items-center">
                      {selectedFile ? (
                        <>
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-blue-400 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                          </svg>
                          <span className={`${theme.text.primary} font-medium mb-1 truncate max-w-[200px]`}>{selectedFile.name}</span>
                          <span className="text-sm text-gray-400">{Math.round(selectedFile.size / 1024)} KB</span>
                        </>
                      ) : (
                        <>
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-gray-400 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0l-4 4m4-4v12" />
                          </svg>
                          <span className={`${theme.text.secondary} font-medium mb-1`}>Click to upload a PDF</span>
                          <span className="text-sm text-gray-400">or drag and drop here</span>
                        </>
                      )}
                    </label>
                  </div>
                </div>
                
                {/* Book Info Fields */}
                <div className="space-y-2">
                  <label className={`block text-sm font-medium ${theme.text.secondary}`}>Title</label>
                  <input
                    type="text"
                    name="title"
                    value={uploadForm.title}
                    onChange={handleUploadFormChange}
                    className="w-full px-4 py-2 bg-gray-800/70 text-white rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/50 border border-gray-700/30"
                    placeholder="Book title"
                    required
                  />
                </div>
                
                <div className="space-y-2">
                  <label className={`block text-sm font-medium ${theme.text.secondary}`}>Author</label>
                  <input
                    type="text"
                    name="author"
                    value={uploadForm.author}
                    onChange={handleUploadFormChange}
                    className="w-full px-4 py-2 bg-gray-800/70 text-white rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/50 border border-gray-700/30"
                    placeholder="Author name"
                  />
                </div>
                
                <div className="space-y-2">
                  <label className={`block text-sm font-medium ${theme.text.secondary}`}>Category</label>
                  <input
                    type="text"
                    name="category"
                    value={uploadForm.category}
                    onChange={handleUploadFormChange}
                    className="w-full px-4 py-2 bg-gray-800/70 text-white rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/50 border border-gray-700/30"
                    placeholder="e.g. Academic, Fiction, etc."
                  />
                </div>
                
                <div className="space-y-2">
                  <label className={`block text-sm font-medium ${theme.text.secondary}`}>Description</label>
                  <textarea
                    name="description"
                    value={uploadForm.description}
                    onChange={handleUploadFormChange}
                    className="w-full px-4 py-2 bg-gray-800/70 text-white rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/50 border border-gray-700/30 min-h-[80px]"
                    placeholder="Short description of the book"
                  />
                </div>
                
                <motion.button
                  type="submit"
                  className="w-full px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-700 text-white rounded-xl shadow-lg hover:from-blue-700 hover:to-indigo-800 border border-blue-500/30 font-medium relative overflow-hidden group"
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  disabled={!selectedFile}
                >
                  <div className="absolute inset-0 bg-gradient-to-r from-blue-400/20 to-indigo-400/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                  <span>Upload Book</span>
                </motion.button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

export default Books; 