import React, { useRef } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';

const ParallaxBackground = () => {
  const containerRef = useRef(null);
  const { scrollY } = useScroll();
  
  // Create parallax effect for different layers
  const layer1Y = useTransform(scrollY, [0, 1000], [0, -150]);
  const layer2Y = useTransform(scrollY, [0, 1000], [0, -100]);
  const layer3Y = useTransform(scrollY, [0, 1000], [0, -50]);
  const layer4Y = useTransform(scrollY, [0, 1000], [0, -25]);
  
  // Optional horizontal parallax
  const layer1X = useTransform(scrollY, [0, 1000], [0, -50]);
  const layer2X = useTransform(scrollY, [0, 1000], [0, 50]);
  
  // Opacity for fade effect
  const layer1Opacity = useTransform(scrollY, [0, 300], [1, 0.5]);
  const layer4Opacity = useTransform(scrollY, [0, 300], [0.3, 0.8]);
  
  return (
    <div 
      ref={containerRef} 
      className="fixed top-0 left-0 w-full h-full overflow-hidden -z-10 pointer-events-none"
    >
      {/* Gradient background - always visible */}
      <div className="absolute inset-0 bg-gradient-to-br from-gray-900 via-blue-900 to-gray-900" />
      
      {/* Stars layer - farthest and slowest */}
      <motion.div 
        className="absolute inset-0 w-full h-full"
        style={{ y: layer1Y, x: layer1X, opacity: layer1Opacity }}
      >
        {Array.from({ length: 50 }).map((_, i) => (
          <motion.div
            key={`star-${i}`}
            className="absolute rounded-full bg-white"
            style={{
              top: `${Math.random() * 100}%`,
              left: `${Math.random() * 100}%`,
              width: `${Math.random() * 3 + 1}px`,
              height: `${Math.random() * 3 + 1}px`,
            }}
            animate={{ 
              opacity: [0.3, 1, 0.3],
              scale: [1, 1.2, 1]
            }}
            transition={{ 
              duration: Math.random() * 3 + 2,
              repeat: Infinity,
              delay: Math.random() * 5
            }}
          />
        ))}
      </motion.div>
      
      {/* Cloud layer */}
      <motion.div 
        className="absolute inset-0 w-full h-full"
        style={{ y: layer2Y, x: layer2X }}
      >
        <svg width="100%" height="100%" viewBox="0 0 1000 1000" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
          <motion.path
            d="M0,200 Q150,150 300,200 T600,150 T900,200 V1000 H0 Z"
            fill="#1E3A8A"
            fillOpacity="0.1"
            initial={{ d: "M0,200 Q150,150 300,200 T600,150 T900,200 V1000 H0 Z" }}
            animate={{ 
              d: [
                "M0,200 Q150,150 300,200 T600,150 T900,200 V1000 H0 Z",
                "M0,180 Q150,220 300,180 T600,220 T900,180 V1000 H0 Z",
                "M0,200 Q150,150 300,200 T600,150 T900,200 V1000 H0 Z"
              ]
            }}
            transition={{ duration: 20, repeat: Infinity, repeatType: "reverse" }}
          />
        </svg>
      </motion.div>
      
      {/* Mid-layer elements */}
      <motion.div 
        className="absolute inset-0 w-full h-full"
        style={{ y: layer3Y }}
      >
        {/* Abstract shapes */}
        <svg width="100%" height="100%" viewBox="0 0 1000 1000" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
          <motion.circle
            cx="200"
            cy="300"
            r="50"
            fill="#2563EB"
            fillOpacity="0.15"
            initial={{ r: 50 }}
            animate={{ r: [50, 60, 50] }}
            transition={{ duration: 8, repeat: Infinity }}
          />
          <motion.circle
            cx="800"
            cy="200"
            r="70"
            fill="#3B82F6"
            fillOpacity="0.1"
            initial={{ r: 70 }}
            animate={{ r: [70, 55, 70] }}
            transition={{ duration: 10, repeat: Infinity }}
          />
          <motion.rect
            x="600"
            y="500"
            width="100"
            height="100"
            rx="20"
            fill="#60A5FA"
            fillOpacity="0.08"
            initial={{ rotate: 0 }}
            animate={{ rotate: 360 }}
            transition={{ duration: 30, repeat: Infinity, ease: "linear" }}
            style={{ transformOrigin: "650px 550px" }}
          />
        </svg>
      </motion.div>
      
      {/* Foreground layer - closest and fastest */}
      <motion.div 
        className="absolute inset-0 w-full h-full"
        style={{ y: layer4Y, opacity: layer4Opacity }}
      >
        <svg width="100%" height="100%" viewBox="0 0 1000 1000" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
          <motion.path
            d="M0,800 Q150,750 300,800 T600,750 T900,800 V1000 H0 Z"
            fill="url(#grad1)"
            fillOpacity="0.2"
            initial={{ d: "M0,800 Q150,750 300,800 T600,750 T900,800 V1000 H0 Z" }}
            animate={{ 
              d: [
                "M0,800 Q150,750 300,800 T600,750 T900,800 V1000 H0 Z",
                "M0,780 Q150,820 300,780 T600,820 T900,780 V1000 H0 Z",
                "M0,800 Q150,750 300,800 T600,750 T900,800 V1000 H0 Z"
              ]
            }}
            transition={{ duration: 12, repeat: Infinity }}
          />
          
          <defs>
            <linearGradient id="grad1" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#2563EB" stopOpacity="0.7" />
              <stop offset="100%" stopColor="#60A5FA" stopOpacity="0.7" />
            </linearGradient>
          </defs>
        </svg>
        
        {/* Floating particles */}
        {Array.from({ length: 20 }).map((_, i) => (
          <motion.div
            key={`particle-${i}`}
            className="absolute rounded-full bg-blue-300"
            style={{
              top: `${Math.random() * 100}%`,
              left: `${Math.random() * 100}%`,
              width: `${Math.random() * 6 + 2}px`,
              height: `${Math.random() * 6 + 2}px`,
              opacity: 0.3,
            }}
            animate={{ 
              y: [0, -50, 0],
              x: [0, Math.random() * 30 - 15, 0],
              opacity: [0.3, 0.5, 0.3]
            }}
            transition={{ 
              duration: Math.random() * 5 + 10,
              repeat: Infinity,
              repeatType: "reverse",
              delay: Math.random() * 5
            }}
          />
        ))}
      </motion.div>
      
      {/* Optional vignette overlay */}
      <div className="absolute inset-0 bg-radial-gradient pointer-events-none" />
    </div>
  );
};

export default ParallaxBackground; 