import React, { useState, useEffect } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { AnimatePresence } from 'framer-motion';
import './App.css';

// Components
import DockBar from './components/DockBar';
import AnimatedNotificationBar from './components/AnimatedNotificationBar';
import CircularProgressBar from './components/CircularProgressBar';
import ParallaxBackground from './components/ParallaxBackground';

// Context Providers
import { NotificationProvider } from './components/NotificationContext';
import { ThemeProvider, ThemeToggle, ThemeTransition } from './contexts/ThemeContext';
import { NavigationProvider } from './contexts/NavigationContext';

// Pages/Views
import Dashboard from './pages/Dashboard';
import Tasks from './pages/Tasks';
import Pomodoro from './pages/Pomodoro';
import Books from './pages/Books';
import Profile from './pages/Profile';
import Calendar from './pages/Calendar';
import Statistics from './pages/Statistics';

// Demo Data
const demoStudyData = [
  { day: 'Mon', value: 120 },
  { day: 'Tue', value: 90 },
  { day: 'Wed', value: 150 },
  { day: 'Thu', value: 85 },
  { day: 'Fri', value: 200 },
  { day: 'Sat', value: 60 },
  { day: 'Sun', value: 30 }
];

const demoTasks = [
  {
    id: 1,
    title: 'Complete React assignment',
    difficulty: 'hard',
    estimatedTime: 60,
    completed: false,
    progress: 30
  },
  {
    id: 2,
    title: 'Review notes on JavaScript closures',
    difficulty: 'medium',
    estimatedTime: 30,
    completed: false,
    progress: 0
  },
  {
    id: 3,
    title: 'Read chapter 4 of textbook',
    difficulty: 'easy',
    estimatedTime: 45,
    completed: true,
    progress: 100
  }
];

const demoBookPages = [
  {
    title: "Introduction to React",
    content: "React is a JavaScript library for building user interfaces. It is maintained by Facebook and a community of individual developers and companies.",
    background: ""
  },
  {
    title: "Components",
    content: "React components are the building blocks of React applications. They are reusable and can be nested inside other components.",
    background: ""
  },
  {
    title: "State & Props",
    content: "State is a JavaScript object that stores a component's dynamic data and determines how the component renders and behaves. Props are inputs to a React component.",
    background: ""
  }
];

function App() {
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('dashboard');

  useEffect(() => {
    // Simpler and more direct approach to ensure scrolling works
    document.body.style.overflow = 'auto';
    document.body.style.height = 'auto';
    document.documentElement.style.overflow = 'auto'; 
    document.documentElement.style.height = 'auto';
    
    return () => {
      // No need to restore - always allow scrolling
    };
  }, []);

  useEffect(() => {
    // Simulate loading time
    const timer = setTimeout(() => {
      setLoading(false);
    }, 1500);

    return () => clearTimeout(timer);
  }, []);

  const handleTabChange = (tabId) => {
    setActiveTab(tabId);
  };

  return (
    <ThemeProvider>
      <ThemeTransition>
        <NotificationProvider>
          <NavigationProvider>
            <div className="App relative min-h-screen overflow-x-hidden">
              {/* Background Effects */}
              <ParallaxBackground />
              
              {/* Loading Screen */}
              {loading ? (
                <div className="loading absolute inset-0 flex items-center justify-center bg-gradient-to-br from-gray-900 via-blue-900 to-gray-900 z-50">
                  <div className="flex flex-col items-center">
                    <CircularProgressBar 
                      progress={100} 
                      status="inProgress" 
                      animationDuration={1.5}
                    >
                      <svg viewBox="0 0 16 16" className="w-10 h-10 text-white">
                        <path 
                          fill="currentColor" 
                          d="M11.182.008C11.148-.03 9.923.023 8.857 1.18c-1.066 1.156-.902 2.482-.878 2.516.024.034 1.52.087 2.475-1.258.955-1.345.762-2.391.728-2.43zm3.314 11.733c-.048-.096-2.325-1.234-2.113-3.422.212-2.189 1.675-2.789 1.698-2.854.023-.065-.597-.79-1.254-1.157a3.692 3.692 0 0 0-1.563-.434c-.108-.003-.483-.095-1.254.116-.508.139-1.653.589-1.968.607-.316.018-1.256-.522-2.267-.665-.647-.125-1.333.131-1.824.328-.49.196-1.422.754-2.074 2.237-.652 1.482-.311 3.83-.067 4.56.244.729.625 1.924 1.273 2.796.576.984 1.34 1.667 1.659 1.899.319.232 1.219.386 1.843.067.502-.308 1.408-.485 1.766-.472.357.013 1.061.154 1.782.539.571.197 1.111.115 1.652-.105.541-.221 1.324-1.059 2.238-2.758.347-.79.505-1.217.473-1.282z" 
                        />
                      </svg>
                    </CircularProgressBar>
                    <h1 className="text-2xl font-bold text-white mt-6 animate-pulse">
                      Loading Study Tracker
                    </h1>
                  </div>
                </div>
              ) : (
                <>
                  {/* Theme Toggle Button */}
                  <div className="fixed top-4 right-4 z-50">
                    <ThemeToggle className="bg-gray-800 bg-opacity-50 text-white" />
                  </div>
                  
                  {/* Notification Bar */}
                  <AnimatedNotificationBar />
                  
                  {/* Main Content Area - improved padding for dock */}
                  <main className="pt-4 md:pt-6 pb-24 px-3 md:px-4 min-h-screen overflow-y-auto overflow-x-hidden" 
                        style={{height: "calc(100vh - 80px)", position: "relative", WebkitOverflowScrolling: "touch"}}>
                    <AnimatePresence mode="wait" initial={false}>
                      <Routes>
                        <Route path="/" element={<Navigate to="/dashboard" />} />
                        <Route path="/dashboard" element={
                          <Dashboard 
                            studyData={demoStudyData} 
                            tasks={demoTasks}
                          />
                        } />
                        <Route path="/tasks" element={
                          <Tasks tasks={demoTasks} />
                        } />
                        <Route path="/pomodoro" element={
                          <Pomodoro tasks={demoTasks} />
                        } />
                        <Route path="/books" element={
                          <Books pages={demoBookPages} />
                        } />
                        <Route path="/calendar" element={
                          <Calendar />
                        } />
                        <Route path="/statistics" element={
                          <Statistics />
                        } />
                        <Route path="/profile" element={
                          <Profile studyData={demoStudyData} tasks={demoTasks} />
                        } />
                        <Route path="*" element={<Navigate to="/dashboard" />} />
                      </Routes>
                    </AnimatePresence>
                  </main>
                  
                  {/* Dock Bar */}
                  <DockBar activeTab={activeTab} setActiveTab={handleTabChange} />
                </>
              )}
            </div>
          </NavigationProvider>
        </NotificationProvider>
      </ThemeTransition>
    </ThemeProvider>
  );
}

export default App;
