import React from 'react';
import { motion } from 'framer-motion';
import {
  IconDashboard,
  IconTasks,
  IconProfile,
  IconPomodoro,
  IconBook,
  IconCalendar,
  IconStatistics
} from '../assets/icons';
import { useNavigate, useLocation } from 'react-router-dom';

const DockIcon = ({ icon: Icon, label, onClick, isActive, to }) => {
  return (
    <motion.div
      className="flex flex-col items-center justify-center cursor-pointer touch-manipulation"
      whileHover={{ 
        scale: 1.1,
        y: -5,
        transition: { 
          type: "spring", 
          stiffness: 400, 
          damping: 10
        } 
      }}
      whileTap={{ scale: 0.9 }}
      onClick={() => onClick(to)}
    >
      <motion.div 
        className={`p-2 sm:p-2.5 rounded-xl ${
          isActive 
            ? 'bg-gradient-to-b from-blue-500 to-blue-600 text-white shadow-lg shadow-blue-600/20' 
            : 'bg-gray-800/70 text-white'
        } relative overflow-hidden`}
        whileHover={{ 
          boxShadow: "0 0 15px rgba(59, 130, 246, 0.3)"
        }}
      >
        {isActive && (
          <div className="absolute inset-0 bg-gradient-to-t from-blue-400/20 to-indigo-400/5 opacity-50"></div>
        )}
        <Icon size={24} className="w-6 h-6 sm:w-7 sm:h-7" />
      </motion.div>
      <span className={`text-xs mt-1 ${isActive ? 'text-white font-medium' : 'text-gray-400'}`}>
        {label}
      </span>
    </motion.div>
  );
};

const DockBar = ({ activeTab, setActiveTab }) => {
  const navigate = useNavigate();
  const location = useLocation();
  
  const currentPath = location.pathname.substring(1) || 'dashboard';
  
  const dockItems = [
    { id: 'dashboard', icon: IconDashboard, label: 'Home', path: '/dashboard' },
    { id: 'tasks', icon: IconTasks, label: 'Tasks', path: '/tasks' },
    { id: 'pomodoro', icon: IconPomodoro, label: 'Timer', path: '/pomodoro' },
    { id: 'books', icon: IconBook, label: 'Books', path: '/books' },
    { id: 'profile', icon: IconProfile, label: 'Profile', path: '/profile' },
  ];
  
  React.useEffect(() => {
    setActiveTab(currentPath);
  }, [currentPath, setActiveTab]);
  
  const handleIconClick = (path) => {
    const tabId = path.substring(1);
    setActiveTab(tabId);
    navigate(path);
  };

  return (
    <motion.div 
      className="fixed bottom-0 left-0 right-0 bg-gray-900/95 backdrop-blur-md border-t border-gray-800/70 shadow-lg py-2 z-40"
      initial={{ y: 100 }}
      animate={{ y: 0 }}
      transition={{ type: "spring", stiffness: 300, damping: 30 }}
    >
      <div className="max-w-screen-xl mx-auto px-2 py-1">
        <div className="flex items-center justify-around gap-1 sm:gap-2">
          {dockItems.map((item) => (
            <DockIcon
              key={item.id}
              icon={item.icon}
              label={item.label}
              isActive={activeTab === item.id}
              onClick={handleIconClick}
              to={item.path}
            />
          ))}
        </div>
      </div>
      
      {/* Safe area inset for iOS devices */}
      <div className="h-safe-area-inset-bottom bg-gray-900"></div>
    </motion.div>
  );
};

export default DockBar; 