import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNotification } from './NotificationContext';

const AnimatedNotificationBar = () => {
  const { notifications, dismissNotification } = useNotification();

  // Different styling based on notification type
  const getNotificationStyle = (type) => {
    switch(type) {
      case 'success':
        return 'bg-green-500 text-white';
      case 'error':
        return 'bg-red-500 text-white';
      case 'warning':
        return 'bg-yellow-500 text-white';
      case 'info':
      default:
        return 'bg-blue-500 text-white';
    }
  };

  return (
    <div className="fixed top-0 left-0 right-0 z-50 px-4 pt-4" style={{pointerEvents: 'none'}}>
      <AnimatePresence>
        {notifications.map((notification) => (
          <motion.div
            key={notification.id}
            className={`${getNotificationStyle(notification.type)} rounded-lg shadow-lg p-4 mb-3 mx-auto max-w-md flex items-center justify-between`}
            initial={{ opacity: 0, y: -50, scale: 0.3 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, scale: 0.5, transition: { duration: 0.2 } }}
            style={{pointerEvents: 'auto'}}
          >
            <span>{notification.message}</span>
            <button 
              onClick={() => dismissNotification(notification.id)}
              className="ml-4 text-white focus:outline-none"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </motion.div>
        ))}
      </AnimatePresence>
    </div>
  );
};

export default AnimatedNotificationBar; 