import React from 'react';
import { motion } from 'framer-motion';

const CIRCLE_SIZE = 120;
const CIRCLE_RADIUS = 50;
const CIRCLE_STROKE = 10;
const CIRCUMFERENCE = 2 * Math.PI * CIRCLE_RADIUS;

const statusColors = {
  completed: '#10B981', // green-500
  inProgress: '#3B82F6', // blue-500
  pending: '#F59E0B', // amber-500
};

const CircularProgressBar = ({ 
  progress = 0, 
  status = 'pending', 
  size = CIRCLE_SIZE,
  strokeWidth = CIRCLE_STROKE,
  children,
  animationDuration = 2,
  title = ''
}) => {
  // Scale dimensions if size is different from default
  const radius = (CIRCLE_RADIUS / CIRCLE_SIZE) * size;
  const normalizedStroke = (CIRCLE_STROKE / CIRCLE_SIZE) * size;
  const normalizedProgress = progress > 100 ? 100 : progress < 0 ? 0 : progress;
  
  // Calculate the strokeDashoffset based on progress percentage
  const strokeDashoffset = CIRCUMFERENCE - (normalizedProgress / 100) * CIRCUMFERENCE;
  
  // Get color based on status
  const strokeColor = statusColors[status] || statusColors.pending;
  
  return (
    <div className="flex flex-col items-center">
      {title && <h3 className="text-lg font-medium mb-2 text-white">{title}</h3>}
      <div className="relative" style={{ width: size, height: size }}>
        {/* Background circle */}
        <svg
          width={size}
          height={size}
          viewBox={`0 0 ${size} ${size}`}
          className="absolute top-0 left-0"
        >
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            stroke="#374151" // gray-700
            strokeWidth={strokeWidth}
            strokeOpacity="0.4"
          />
        </svg>
        
        {/* Progress circle */}
        <svg
          width={size}
          height={size}
          viewBox={`0 0 ${size} ${size}`}
          className="absolute top-0 left-0 transform -rotate-90"
        >
          <motion.circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            stroke={strokeColor}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            initial={{ strokeDasharray: CIRCUMFERENCE, strokeDashoffset: CIRCUMFERENCE }}
            animate={{ strokeDashoffset }}
            transition={{ 
              duration: animationDuration, 
              ease: "easeInOut"
            }}
            style={{
              strokeDasharray: CIRCUMFERENCE,
            }}
          />
        </svg>
        
        {/* Content inside circle */}
        <div className="absolute inset-0 flex items-center justify-center">
          {children || (
            <motion.div 
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ 
                delay: animationDuration * 0.5, 
                type: "spring", 
                stiffness: 200, 
                damping: 15 
              }}
              className="text-center"
            >
              <motion.span 
                className="text-2xl font-bold text-white"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: animationDuration * 0.7 }}
              >
                {Math.round(normalizedProgress)}%
              </motion.span>
            </motion.div>
          )}
        </div>
        
        {/* Glow effect for completed tasks */}
        {status === 'completed' && (
          <motion.div 
            className="absolute inset-0 rounded-full"
            initial={{ boxShadow: "0 0 0 rgba(16, 185, 129, 0)" }}
            animate={{ boxShadow: "0 0 15px rgba(16, 185, 129, 0.6)" }}
            transition={{ 
              duration: 1.5, 
              repeat: Infinity, 
              repeatType: "reverse" 
            }}
          />
        )}
      </div>
    </div>
  );
};

export default CircularProgressBar; 